{
  "title": "The Rescue of Ember Hollow",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small band approaches the ruined royal city at dusk.",
      "visual_description": "Wide shot of four travelers cresting a hill, the broken silhouette of a fallen royal city sprawled below, banners torn in the wind, sky bruised orange and violet.",
      "characters": ["Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin"]
    },
    {
      "scene_number": 2,
      "caption": "Mira unrolls a map of the city by lantern light.",
      "visual_description": "Close shot of weathered hands pinning a vellum map to a stone, glowing lantern casting amber light, ink markings circling the inner keep.",
      "characters": ["Mira the Pathfinder", "Captain Roen"]
    },
    {
      "scene_number": 3,
      "caption": "The team slips past the rusted castle gates.",
      "visual_description": "Towering iron gates hanging crookedly off their hinges, vines threading through the bars, four cloaked figures crouched in the shadow of a fallen portcullis.",
      "characters": ["Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin"]
    },
    {
      "scene_number": 4,
      "caption": "Frightened townspeople peer from a boarded-up alley.",
      "visual_description": "Narrow alley lit by a single guttering torch, pale faces of villagers framed between cracked shutters, a small child clutching a cloth doll.",
      "characters": ["Captain Roen", "Mira the Pathfinder", "Goodwife Hesta", "the Lantern Child"]
    },
    {
      "scene_number": 5,
      "caption": "Hesta whispers what happened to the captured prince.",
      "visual_description": "Tight interior shot of a candle-lit cellar, Hesta gesturing toward a hand-drawn sketch of a tower, fear etched on her face.",
      "characters": ["Goodwife Hesta", "Captain Roen", "Brindle the Hedge-Mage"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches down the main avenue.",
      "visual_description": "Low angle of black-plated soldiers in lockstep along a moonlit boulevard, banners of a usurper crest snapping above them, the team pressed flat behind a toppled statue.",
      "characters": ["Captain Roen", "Sir Olwin", "Mira the Pathfinder", "Iron Marshal Vex"]
    },
    {
      "scene_number": 7,
      "caption": "Sir Olwin dozes against a column and nearly gives them away.",
      "visual_description": "Comic medium shot of a portly knight snoring with helmet askew, a startled pigeon flapping off his pauldron, Mira lunging to clamp his mouth.",
      "characters": ["Sir Olwin", "Mira the Pathfinder"]
    },
    {
      "scene_number": 8,
      "caption": "They debate the rumored dragon in the cathedral ruins.",
      "visual_description": "Group huddled in a roofless cathedral, shafts of moonlight on broken pews, Brindle pointing up at huge claw-scored stones overhead.",
      "characters": ["Brindle the Hedge-Mage", "Captain Roen", "Mira the Pathfinder", "Sir Olwin"]
    },
    {
      "scene_number": 9,
      "caption": "Mira chooses the long route around the cursed tower.",
      "visual_description": "Sweeping shot of a black spiral tower wreathed in greenish mist, Mira's finger tracing a detour on her map, the others nodding gravely.",
      "characters": ["Mira the Pathfinder", "Captain Roen", "Brindle the Hedge-Mage"]
    },
    {
      "scene_number": 10,
      "caption": "Brindle calms a sentry hound with a soft charm.",
      "visual_description": "A gaunt armored hound bathed in pale blue rune-light, Brindle kneeling with palm outstretched, soft sparks drifting between his fingers.",
      "characters": ["Brindle the Hedge-Mage", "the Sentry Hound"]
    },
    {
      "scene_number": 11,
      "caption": "They reach a sealed magic door carved with royal sigils.",
      "visual_description": "Massive arched door of black stone, glowing silver runes pulsing across its surface, the group dwarfed beneath it, torchlight flickering on their faces.",
      "characters": ["Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin"]
    },
    {
      "scene_number": 12,
      "caption": "Brindle solves the rune lock and the door grinds open.",
      "visual_description": "Close-up of Brindle's hand pressing a central rune, light cascading outward like ripples, the door splitting with dust and pale inner glow.",
      "characters": ["Brindle the Hedge-Mage", "Captain Roen"]
    },
    {
      "scene_number": 13,
      "caption": "They find Prince Aldric chained in a banner-draped hall.",
      "visual_description": "Cavernous throne hall hung with tattered royal banners, a young prince in torn finery shackled to a broken throne, dust motes swirling in shafts of light.",
      "characters": ["Prince Aldric", "Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin"]
    },
    {
      "scene_number": 14,
      "caption": "Sir Olwin shatters the prince's chains with a great swing.",
      "visual_description": "Dynamic shot of Olwin mid-strike, greatsword arcing, broken iron links flying, the prince shielding his face as Roen catches his shoulder.",
      "characters": ["Sir Olwin", "Prince Aldric", "Captain Roen"]
    },
    {
      "scene_number": 15,
      "caption": "Iron Marshal Vex arrives with his patrol at the hall doors.",
      "visual_description": "Wide shot of a black-armored marshal framed in the doorway, helm crowned with iron antlers, soldiers fanning behind him, torches flaring.",
      "characters": ["Iron Marshal Vex", "Captain Roen", "Sir Olwin", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "The group flees through twisting streets toward the river.",
      "visual_description": "Overhead chase shot of the five sprinting through rubble-strewn lanes, arrows skittering off cobblestones, the glint of water visible beyond a far archway.",
      "characters": ["Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin", "Prince Aldric"]
    },
    {
      "scene_number": 17,
      "caption": "Brindle collapses the stone bridge behind them as they cross.",
      "visual_description": "Long shot of an ancient arched bridge over a black river, the rear span crumbling into spray under a burst of green magelight, soldiers stranded on the far bank.",
      "characters": ["Brindle the Hedge-Mage", "Captain Roen", "Mira the Pathfinder", "Sir Olwin", "Prince Aldric", "Iron Marshal Vex"]
    },
    {
      "scene_number": 18,
      "caption": "On the far hill, the prince looks back at the ruined city at dawn.",
      "visual_description": "Quiet wide shot at sunrise, the rescued prince wrapped in Roen's cloak, the team silhouetted on a grassy ridge, broken city skyline glowing pink in the distance.",
      "characters": ["Prince Aldric", "Captain Roen", "Mira the Pathfinder", "Brindle the Hedge-Mage", "Sir Olwin"]
    }
  ]
}

